import React from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import './App.css';

function App() {
  return (
    <div className="min-h-screen bg-mystery-dark">
      <Navbar />
      <Hero />
      <main className="container mx-auto px-4 py-8">
        <Features />
        <TradingStats />
      </main>
    </div>
  );
}

export default App;
